  ('def', '<b>wait = random(0, min(cap, base × 2^attempt))</b> ("full jitter"). If the server sends <code>Retry-After</code>, obey it first.'),
  ('code', 'import random, time\nRETRYABLE = {429, 500, 503, 529}\ndef call_with_backoff(send, base=0.5, cap=30.0, max_attempts=6):\n    for attempt in range(max_attempts):\n        resp = send()\n        if resp.status not in RETRYABLE: return resp\n        ra = resp.headers.get("retry-after")\n        time.sleep(float(ra) if ra else random.uniform(0, min(cap, base * 2 ** attempt)))\n    raise RuntimeError("gave up")'),
